for x in j['performance']:
 host='Chrome'if x['host']=='Chrome'else'WK';model=x['matting'];ep='—'if model=='mediapipe'else('WebGPU'if x['backend']=='webgpu'else'WASM');mp=('WebGL'if x['backend']=='gpu'else'CPU')if model=='mediapipe'else('CPU'if x['gateBackend']else'—');bad=' class="failed"'if x['over16']else''
 parts.append(f"<tr><td>{host} {model}</td><td>{x['mode']}</td><td>{ep}</td><td>{mp}</td><td>{x['fps']:.2f}</td><td>{x['matteFps']:.2f}</td><td>{x['rvmMs']:.2f}</td><td>{x['mpMs']:.2f}</td><td{bad}>{x['over16']}</td><td{bad}>{x['maxCallback']:.1f}</td></tr>")
parts.append('''</tbody></table></div><p><small>720p, 30fps public source. FPS is preview cadence; mattes/s is delivered model output. MP ms includes worker inference, gate/cleanup and output preparation. Slow WASM is forced only for measurement; production auto falls back. Native uses tauri://localhost and the exact CSP. Startup is retained separately. The pre-taper native Replace run had two callbacks over 16ms (39ms maximum), so a hard bound is not established by a later passing window.</small></p>
<h3>Leakage proxy — native, recurrent frames</h3><p><small>Percent of pixels outside MP confidence ≥0.65 dilated by 24px that have alpha &gt;0.5. First ten frames excluded. This is a proxy, not ground truth: MP-missed real sleeves and people count as leakage.</small></p><table><thead><tr><th>Public scene</th><th>RVM %</th><th>MP %</th><th>Hybrid %</th></tr></thead><tbody>''')
for x in j['quality']['native-quality']['summary']:
 parts.append(f"<tr><td>{html.escape(x['clip'])}</td><td>{x['rvm']:.4f}</td><td>{x['mediapipe']:.4f}</td><td class=\"strong\">{x['hybrid']:.4f}</td></tr>")
parts.append('</tbody></table>')
q=j['quality']['chrome-quality']['summary'];chair=next(x for x in q if x['clip']=='chair');parts.append(f"<p><small>Chrome chair proxy: {chair['rvm']:.4f}% → {chair['hybrid']:.4f}%. All 840 frames were processed in each host. The bright-wall office clip produced no large plume in RVM, so it cannot prove the reported regression fixed.</small></p>")
if j['soak']:
 s=j['soak'];parts.append(f"<h3>Ten-minute resource soak</h3><p>600 samples / {s['elapsedSeconds']:.1f}s. Median FPS <strong>{s['firstMinuteFps']:.2f} → {s['lastMinuteFps']:.2f}</strong>; RSS <strong>{s['firstMinuteMiB']:.1f} → {s['lastMinuteMiB']:.1f} MiB</strong>; JS heap {s['firstMinuteHeapMiB']:.3f} → {s['lastMinuteHeapMiB']:.3f} MiB. No growth or FPS decay observed. The soak predates the shader-only taper; model, allocation and transport paths are unchanged.</p>")
